select now() at time zone 'utc' as measured_utc;
select t.relname, (xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', t.relname), false, true, '')))[1]::text::bigint as exact_rows, c.relkind, pg_get_userbyid(c.relowner) as owner, exists(select 1 from pg_publication_tables p where p.schemaname='public' and p.tablename=t.relname) as in_publication, exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='e') as in_extension, pg_total_relation_size(c.oid) as bytes from (values ('__agent_runs'),('__catalog_import_history'),('__diag_safe_phrases'),('__marketing_analytics_digests'),('__marketing_content_library'),('__marketing_guest_posts'),('__qa_protected_meta_hash'),('__rag_check_history'),('__rag_pipeline_incidents'),('__rag_readiness'),('__seo_ai_runs'),('__seo_audit_history'),('__seo_cannibalization_recommendations'),('__seo_content_audit'),('__seo_diagnostic'),('__seo_gamme_gsc_baseline'),('__seo_observable_policy'),('__seo_r2_page_content'),('__seo_r2_page_versions'),('__seo_r2_qa_reviews'),('__seo_r2_regeneration_queue'),('__seo_reality_audit'),('__seo_revert_candidates_log'),('__seo_role_content'),('__v_level_computed'),('__v_level_raw'),('error_statistics'),('gamme_filter_criteria'),('kg_audit_log'),('kg_edge_history'),('kg_learning_log'),('kg_node_history'),('kg_weight_adjustments'),('norm_vehicle'),('rm_data_version'),('rm_listing_content'),('rm_oem_top'),('stg_compatibility'),('support_tickets'),('audit_vlevel_pg424_snapshot_20260608')) t(relname) join pg_class c on c.relname=t.relname and c.relnamespace='public'::regnamespace order by 1;
select count(*) as morte_names_in_matview_or_rule from pg_rewrite rw join pg_depend d on d.objid=rw.oid join pg_class c on c.oid=d.refobjid where c.relnamespace='public'::regnamespace and c.relname in ('__agent_runs','__catalog_import_history','__diag_safe_phrases','__marketing_analytics_digests','__marketing_content_library','__marketing_guest_posts','__qa_protected_meta_hash','__rag_check_history','__rag_pipeline_incidents','__rag_readiness','__seo_ai_runs','__seo_audit_history','__seo_cannibalization_recommendations','__seo_content_audit','__seo_diagnostic','__seo_gamme_gsc_baseline','__seo_observable_policy','__seo_r2_page_content','__seo_r2_page_versions','__seo_r2_qa_reviews','__seo_r2_regeneration_queue','__seo_reality_audit','__seo_revert_candidates_log','__seo_role_content','__v_level_computed','__v_level_raw','error_statistics','gamme_filter_criteria','kg_audit_log','kg_edge_history','kg_learning_log','kg_node_history','kg_weight_adjustments','norm_vehicle','rm_data_version','rm_listing_content','rm_oem_top','stg_compatibility','support_tickets','audit_vlevel_pg424_snapshot_20260608') and rw.ev_class<>c.oid;
